repo_files.indexer.py:
"""Rotated sorted array minimum pivot indexer."""

from typing import List


class RotatedIndexer:
    def __init__(self, nums: List[int]):
        self.nums = nums

    def find_pivot_index(self) -> int:
        """Returns the index of the minimum element in rotated sorted array."""
        if not self.nums:
            return -1
        left, right = 0, len(self.nums) - 1
        while left < right:
            mid = (left + right) // 2
            # BUG: Compares mid against left element instead of right boundary element,
            # failing to converge on the minimum pivot in unrotated and multi-element arrays!
            if self.nums[mid] < self.nums[left]:
                right = mid
            else:
                left = mid + 1
        return left

repo_files.search.py:
"""Search service utilizing rotated pivot index."""

from typing import List
from indexer import RotatedIndexer


class SearchService:
    @staticmethod
    def find_minimum_value(dataset: List[int]) -> int:
        if not dataset:
            return -1
        idx = RotatedIndexer(dataset)
        pivot_pos = idx.find_pivot_index()
        return dataset[pivot_pos]

